#!/bin/zsh
# Generates a local test playlist with synthetic test-pattern videos and
# serves it on http://127.0.0.1:${PORT:-48300}/playlist.m3u
#
#   tool/make_fixtures.sh <output-dir>          # create files and serve
#   SERVE=0 tool/make_fixtures.sh <output-dir>  # create files only
#
# Everything is generated by ffmpeg (test pattern with a seconds counter,
# tones, a generated subtitle), so no third-party content is involved. Needs ffmpeg and python3.
set -euo pipefail
OUT=${1:?output directory}
PORT=${PORT:-48300}
BASE="http://127.0.0.1:$PORT"
mkdir -p "$OUT/movie" "$OUT/series/test-show" "$OUT/live"

clip() { # file seconds label [extra args...]
  local f=$1 secs=$2 label=$3; shift 3
  [[ -f $f ]] && return
  ffmpeg -loglevel error -y \
    -f lavfi -i "testsrc=size=640x360:rate=25:duration=$secs" \
    -f lavfi -i "sine=frequency=440:duration=$secs" \
    -c:v libx264 -preset veryfast -b:v 400k -c:a aac -b:a 64k -shortest "$@" "$f"
}

# A movie with two audio tracks and an embedded English subtitle track.
SRT="$OUT/movie/subs.srt"
cat > "$SRT" <<'SRT'
1
00:00:02,000 --> 00:00:08,000
Embedded test subtitle (English)

2
00:00:10,000 --> 00:00:20,000
Second embedded subtitle line
SRT
M="$OUT/movie/test-pattern-film.mp4"
if [[ ! -f $M ]]; then
  ffmpeg -loglevel error -y \
    -f lavfi -i "testsrc=size=640x360:rate=25:duration=300" \
    -f lavfi -i "sine=frequency=440:duration=300" \
    -f lavfi -i "sine=frequency=660:duration=300" \
    -i "$SRT" \
    -map 0:v -map 1:a -map 2:a -map 3:s \
    -c:v libx264 -preset veryfast -b:v 400k -c:a aac -b:a 64k -c:s mov_text \
    -metadata:s:a:0 language=eng -metadata:s:a:1 language=fra -metadata:s:s:0 language=eng \
    "$M"
fi
clip "$OUT/movie/short-test-film.mp4" 180 "SHORT FILM"
for e in 1 2 3; do
  clip "$OUT/series/test-show/S01E0$e.mp4" 150 "TEST SHOW S01E0$e"
done

# An HLS "channel" (the short film cut into segments).
[[ -f "$OUT/live/test.m3u8" ]] || ffmpeg -loglevel error -y -i "$OUT/movie/short-test-film.mp4" -c copy \
  -f hls -hls_time 6 -hls_playlist_type vod "$OUT/live/test.m3u8"

# XMLTV guide for that channel: hourly programmes from 24h ago to 24h ahead.
python3 - "$OUT/guide.xml" <<'PY'
import sys, datetime as dt
now = dt.datetime.now(dt.timezone.utc).replace(minute=0, second=0, microsecond=0)
f = lambda t: t.strftime('%Y%m%d%H%M%S +0000')
rows = ['<?xml version="1.0" encoding="UTF-8"?>', '<tv>',
        '<channel id="test.pattern"><display-name>Test Pattern Channel</display-name></channel>']
for h in range(-24, 24):
    s = now + dt.timedelta(hours=h)
    rows.append(f'<programme start="{f(s)}" stop="{f(s + dt.timedelta(hours=1))}" channel="test.pattern">'
                f'<title>Test programme {s:%H}:00</title><desc>Generated guide entry.</desc></programme>')
rows.append('</tv>')
open(sys.argv[1], 'w').write('\n'.join(rows))
PY

cat > "$OUT/playlist.m3u" <<M3U
#EXTM3U url-tvg="$BASE/guide.xml"
#EXTINF:-1 tvg-id="test.pattern" tvg-name="Test Pattern Channel" catchup="append" catchup-days="3" catchup-source="?utc={utc}&lutc={lutc}" group-title="Test Live",Test Pattern Channel
$BASE/live/test.m3u8
#EXTINF:-1 tvg-name="Test Pattern Film (2024)" group-title="Test Movies",Test Pattern Film (2024)
$BASE/movie/test-pattern-film.mp4
#EXTINF:-1 tvg-name="Short Test Film (2023)" group-title="Test Movies",Short Test Film (2023)
$BASE/movie/short-test-film.mp4
#EXTINF:-1 group-title="Test Series",Test Show S01 E01
$BASE/series/test-show/S01E01.mp4
#EXTINF:-1 group-title="Test Series",Test Show S01 E02
$BASE/series/test-show/S01E02.mp4
#EXTINF:-1 group-title="Test Series",Test Show S01 E03
$BASE/series/test-show/S01E03.mp4
M3U
echo "Fixtures ready in $OUT — playlist: $BASE/playlist.m3u"
if [[ ${SERVE:-1} == 1 ]]; then
  exec python3 "${0:A:h}/serve_fixtures.py" "$OUT" "$PORT"
fi
